<template><div v-if="project"><button class="back-btn" @click="$emit('back')"><ChevronLeft/>Voltar para projetos</button><div class="welcome-row"><div><p class="eyebrow">DETALHES DO PROJETO</p><h1>{{project.name}}</h1><p class="subcopy">{{project.description}}</p></div><button v-if="admin" class="primary-btn" @click="$emit('add')"><Plus/>Nova tarefa</button></div><div class="detail-grid"><section class="panel project-summary"><div><span>Progresso</span><strong>{{progress}}%</strong><div class="bar"><i :style="{width:progress+'%',background:project.color}"/></div></div><div><span>Tarefas concluídas</span><strong>{{done}} / {{related.length}}</strong></div><div><span>Prazo</span><strong>{{fmt(project.due)}}</strong></div></section><section class="panel"><div class="panel-head"><div><h2>Membros</h2><p>{{project.members.length}} participantes</p></div></div><div class="member-list"><div v-for="m in project.members.map(id=>members.find(x=>x.id===id)).filter(Boolean)" :key="m!.id"><Avatar :member="m"/><span><strong>{{m!.name}}</strong><small>{{m!.job}}</small></span></div></div></section></div><section class="panel"><div class="panel-head"><div><h2>Tarefas do projeto</h2><p>Entregas relacionadas</p></div></div><div class="table-wrap"><table><tbody><tr v-for="t in related" :key="t.id" @click="$emit('task',t)"><td><strong>{{t.title}}</strong></td><td>{{members.find(m=>m.id===t.assigneeId)?.name}}</td><td>{{t.priority}}</td><td><span :class="['status',t.status==='Concluída'?'green':t.status==='Em andamento'?'blue':'gray']">{{t.status}}</span></td></tr></tbody></table></div></section></div><div v-else class="empty">Projeto não encontrado.</div></template>
<script setup lang="ts">import{computed}from"vue";import{ChevronLeft,Plus}from"lucide-vue-next";import Avatar from"./Avatar.vue";import type{Member,Project,Task}from"../stores/taskflow";const props=defineProps<{project?:Project;tasks:Task[];members:Member[];admin:boolean}>();defineEmits(["back","task","add"]);const related=computed(()=>props.tasks.filter(t=>t.projectId===props.project?.id)),done=computed(()=>related.value.filter(t=>t.status==="Concluída").length),progress=computed(()=>related.value.length?Math.round(done.value/related.value.length*100):0),fmt=(v:string)=>new Intl.DateTimeFormat("pt-BR").format(new Date(v+"T12:00:00"));</script>
